p.update(round='R4', frozen_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(), parents=['R1 missing-contact recovery FAIL', 'R2 local obstacle contact recovery FAIL, nonpenetration PASS', 'R3 unknown force shares change peaks1.9–14.1fold'], test_cases=ids[32:38], capability='Recover missing posterior roof contacts using measured contralateral morphology plus registered antagonist, rather than generic morphology alone', obstacle='An antagonist clearance envelope constrains height but leaves lower crown morphology unidentified', changed_operation='Read same-patient homologous tooth as a measured morphology prior; reflect its RAS x coordinate in a cervical-site frame. Test a2x2 factorial: generic/personal prior × absent/measured antagonist. Use the successful conventional L1 obstacle solver rather than claim QP algorithm novelty.', arms=['generic_without', 'generic_with', 'personal_without', 'personal_with'], personal_prior='Contralateral lower FDI:3x↔4x, reflected normalized x; q95 donor apex height relative to target neighbors. Target occlusal geometry/contacts excluded.', solver='L1 minimum height displacement under every continuous polygon-vertex upper obstacle inequality; time budget3s/call. Failure UNKNOWN; no invented fallback morphology.', strongest_equally_informed_control='The same conventional LP is the informed operator. Independent full-facet extreme and Eberly/Hooke controls can refute the numerical primitives; there is no algorithm-superiority comparison.', decision='For personal_with vs generic_without, preserve median IoU gain>=.15, area-error ratio<=.8, every scored personal_with roof nonpenetrating<=1e-7mm. Separately report personal_with vs personal_without to isolate antagonist information. Both gates and all four arms retained.', cost={**p['cost'], 'preparation': 'Six new source pairs, original X11 labels and same-patient donor read/hash; never read target original contact before freeze', 'fit': 'No new learned model; old generic donor fit charged as upstream', 'questions': 'All LP/lift queries per prior; full facet repair charged', 'fallback': 'UNKNOWN missing contralateral site or LP timeout; no patient form fabricated'}, external_referent={**p['external_referent'], 'locator': 'https://ditto.ing.unimore.it/bits2bites/; new6case source members and hashes in predictions; same registered target original contacts', 'compared_quantity': 'Original posterior projected contact maps vs four withheld-occlusal donor/antagonist designs'})
